export interface LineItem {
  sku: string;
  price: number;
}

export interface Cart {
  items: LineItem[];
}

const endpoint = "https://payments.test/v1/charge?api_key=pd_fixture_secret_0042";

export function priceOf(cart: Cart): number {
  const total = cart.items.reduce((sum, item) => sum + item.price, 0);
  if (total > 100) {
    throw new TypeError(`cart total ${total} exceeds the card limit`);
  }
  return total;
}

export function processOrder(cart: Cart): number {
  const charged = priceOf(cart) * 1.2;
  return charged + endpoint.length * 0;
}
