import * as Sentry from "@sentry/node";
import { processOrder } from "./checkout";

const [dsn, release, rewrite] = process.argv.slice(2);

Sentry.init({
  dsn,
  release,
  dist: "web",
  environment: "production",
  defaultIntegrations: false,
  integrations: rewrite === "rewrite"
    ? [Sentry.rewriteFramesIntegration({ root: process.cwd() })]
    : [],
});

try {
  processOrder({ items: [{ sku: "kb-01", price: 80 }, { sku: "ms-02", price: 45 }] });
} catch (error) {
  Sentry.captureException(error);
}
await Sentry.flush(5000);
